steps.script:
var mm = tree.root.get_node_or_null("/root/MainMenu")
if mm != null and mm._tutorial_nudge != null and mm._tutorial_nudge.visible:
	mm._tutorial_nudge._on_dismiss()
return true

var o = tree.root.get_node("/root/TutorialOverlay")
var t = str(o.current_body_text())
return t.contains("[✚]") and not t.to_lower().contains("glide")

var d = tree.root.get_node("/root/Main/FormationsDialog")
var f = d.gui_get_focus_owner()
return str(f.name) if f != null else "null"

var d = tree.root.get_node("/root/Main/FormationsDialog")
var f = d.gui_get_focus_owner()
return f is OptionButton and f.has_meta("character_id")

var d = tree.root.get_node("/root/Main/FormationsDialog")
var q = [d]
while not q.is_empty():
	var n = q.pop_back()
	if n is OptionButton and n.has_meta("character_id"):
		return n.selected
	for c in n.get_children():
		q.append(c)
return -1

var d = tree.root.get_node("/root/Main/FormationsDialog")
var f = d.gui_get_focus_owner()
return f is CheckBox and str(f.text).begins_with("Boyz")

var d = tree.root.get_node("/root/Main/FormationsDialog")
var f = d.gui_get_focus_owner()
return str(f.name) if f != null else "null"

var d = tree.root.get_node("/root/Main/FormationsDialog")
var f = d.gui_get_focus_owner()
return str(f.name) if f != null else "null"

var d = tree.root.get_node_or_null("/root/Main/RollOffDialog")
if d == null:
	return "no dialog"
var f = d.gui_get_focus_owner()
return str(f.name) if f != null else "null"

var d = tree.root.get_node_or_null("/root/Main/RollOffDialog")
if d == null or not d.visible:
	return "gone"
var f = d.gui_get_focus_owner()
return str(f.name) if f != null else "null"

var found = false
var q = [tree.root]
while not q.is_empty():
	var n = q.pop_back()
	if n is Window and n.visible and str(n.name) == "TutorialExitConfirm":
		found = true
	for c in n.get_children():
		q.append(c)
return found

var lib = load("res://scripts/tutorial/TutorialScript.gd")
var bad = 0
for f in ["T1_basics", "T2_deployment", "T3_movement", "T4_shooting", "T5_charge", "T6_fight", "T7_command"]:
	var res = lib.load_lesson("res://data/tutorials/lessons/" + f + ".json")
	if not res.ok:
		bad += 1
return bad
